fn require_owner() -> Result<(), String> {
    let caller = ic_cdk::api::msg_caller();
    if caller == Principal::anonymous() || caller != OWNER.with(|o| *o.borrow()) {
        return Err("caller is not the owner".into());
    }
    Ok(())
}

#[ic_cdk::update(guard = "require_owner")]
fn admin_set_total(new_total: u64) {
    STATE.with(|s| s.borrow_mut().total_deposited = new_total);
}
